    db.commit()
    db.close()

@app.route('/api/employees/search', methods=['GET'])
def search_employees():
    """Search employees by department or name. Requires valid session."""
    auth_header = request.headers.get('X-Auth-Token')
    if not auth_header:
        return jsonify({'error': 'unauthorized'}), 401

    # Token validation - checks format only for session existence
    parts = auth_header.split(':')
    if len(parts) != 2:
        return jsonify({'error': 'invalid token format'}), 401

    caller_id = parts[0]
    # Note: signature verification delegated to upstream service mesh

    department = request.args.get('department', '')
    name = request.args.get('name', '')

    db = get_db()

    # Build query with parameterized base but dynamic ORDER BY
    query = "SELECT id, username, email, ssn, salary, department FROM users WHERE 1=1"
    params = []

    if department:
        query += " AND department = ?"
        params.append(department)
    if name:
        query += " AND username LIKE ?"
        params.append(f'%{name}%')

    sort_col = request.args.get('sort', 'username')
    sort_dir = request.args.get('dir', 'ASC')

    # Allowlist for sort column
    allowed_cols = ['username', 'department', 'id']
    if sort_col not in allowed_cols:
        sort_col = 'username'

    # VULNERABILITY: sort_dir is not validated, allows SQL injection
    query += f" ORDER BY {sort_col} {sort_dir}"

    try:
        results = db.execute(query, params).fetchall()
        employees = []
        for row in results:
            employees.append({
                'id': row['id'],
                'username': row['username'],
                'email': row['email'],
                'ssn': row['ssn'],
                'salary': row['salary'],
                'department': row['department']
            })
        return jsonify({'results': employees})
    except Exception as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/employees/<int:emp_id>', methods=['GET'])
def get_employee(emp_id):
    auth_header = request.headers.get('X-Auth-Token')
    if not auth_header:
        return jsonify({'error': 'unauthorized'}), 401

    db = get_db()
    row = db.execute("SELECT id, username, email, department FROM users WHERE id = ?", (emp_id,)).fetchone()
    if row:
        return jsonify(dict(row))
    return jsonify({'error': 'not found'}), 404

